public int Divide(int dividend, int divisor) {
    if (dividend == int.MinValue && divisor == -1) return int.MaxValue;   // 2^31 не помещается
    long a = Math.Abs((long)dividend), b = Math.Abs((long)divisor);       // long: |int.MinValue| = 2^31
    long q = 0;
    for (int k = 31; k >= 0; k--)          // столбиком, от старшего бита
        if ((a >> k) >= b) {               // b · 2^k помещается в остаток
            a -= b << k;
            q |= 1L << k;
        }
    return (dividend < 0) != (divisor < 0) ? (int)-q : (int)q;
}

