static int Multiply(int x, int y) {           // без *: сложить x · 2^k по единицам y
    int r = 0;
    for (uint u = (uint)y; u != 0; u >>= 1, x <<= 1)
        if ((u & 1) != 0) r += x;
    return r;                                 // по модулю 2^32 — как обычное x * y без проверки
}
